'use strict';

const _LEO = {
  run:   { n:8,   frames:null, imgs:["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"]   },
  idle:  { n:4,  frames:null, imgs:["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"]  },
  jump:  { n:4,  frames:null, imgs:["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"]  },
  climb: { n:6, frames:null, imgs:["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"] },
};
Object.values(_LEO).forEach(a=>{ a.frames=a.imgs.map(s=>{ const i=new Image(); i.src=s; return i; }); });
const _LEO_DW=52, _LEO_DH=52;
let _leoFI=0, _leoFT=0, _leoKey='idle';

const _ROBO = {
  walk:   { n:8,   frames:null, imgs:["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"]   },
  attack: { n:4, frames:null, imgs:["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"] },
  hurt:   { n:2,   frames:null, imgs:["data:image/png;base64,", "data:image/png;base64,"]   },
};
Object.values(_ROBO).forEach(a=>{ a.frames=a.imgs.map(s=>{ const i=new Image(); i.src=s; return i; }); });
// Robô: 80x80px, proporcional ao tile 48px = 1.67 tiles
const _ROBO_DW=72, _ROBO_DH=72;
const _roboFI={};
let _roboFT=0;

// =====================================================================
// GUARDIÕES DA FAUNA — js/game.js
// Engine 2D completo conforme GDD: física, colisão, IA, animais,
// binóculo, boss com 3 fases, lily pads, mecânicas especiais
// =====================================================================
const Game = (() => {

// ── CONSTANTES ──────────────────────────────────────────────────────
const TILE = 48;
const GRAV = 0.55;
const MAX_FALL = 14;
const RUN_SPD = 3.5;
const JUMP_VY = -11.5;
const DJUMP_VY = -9;
const CLIMB_SPD = 2.2;
const SWIM_SPD = 2.8;
const BEAM_SPD = 12;
const IFRAME_MS = 1200;
const PW = 20, PH = 32;

// ── ESTADO ──────────────────────────────────────────────────────────
let canvas, ctx, lvl, biome, grid, keys, paused = false;
let rafId = null, lastTs = 0;
let player, enemies, animals, beams, particles, floats;
let checks, exitR, lilyPads, nets;
let _binoUsed = false, _startTime = 0, _tookDamage = false;
let _stepTimer = 0;
const cam = {x: 0, y: 0};
const prev = {};

// ── API PÚBLICA ─────────────────────────────────────────────────────
function init(level, inputKeys) {
  canvas = document.getElementById('game-canvas');
  ctx = canvas.getContext('2d');
  ctx.imageSmoothingEnabled = false;
  lvl = level; biome = level.biomeConfig; grid = level.grid; keys = inputKeys;
  paused = false; _binoUsed = false; _tookDamage = false;
  _startTime = performance.now();
  _resize(); _spawn();
  lastTs = performance.now();
  if (rafId) cancelAnimationFrame(rafId);
  rafId = requestAnimationFrame(_loop);
  return { setPaused, onResize: _resize, destroy };
}

function setPaused(v) { paused = !!v; }

function destroy() {
  if (rafId) cancelAnimationFrame(rafId);
  rafId = null;
}

// ── LOOP ────────────────────────────────────────────────────────────
function _loop(ts) {
  rafId = requestAnimationFrame(_loop);
  const dt = Math.min((ts - lastTs) / 16.667, 3);
  lastTs = ts;
  if (!paused) _update(dt);
  _draw();
}

// ── SPAWN ───────────────────────────────────────────────────────────
function _spawn() {
  enemies = lvl.enemySpawns.map(_mkEnemy);
  animals = lvl.animalSpawns.map(_mkAnimal);
  beams = []; particles = []; floats = [];
  checks = lvl.checkpoints.map(c => ({x: c.tx*TILE, y: c.ty*TILE, active: false}));
  const e = lvl.exit;
  exitR = {x: e.tx*TILE, y: e.ty*TILE, w: TILE, h: TILE*2};
  // Lily pads with state
  lilyPads = (lvl.specialZones?.lilyPads || []).map(lp => ({
    tx: lp.tx, sunk: 0, sinking: false
  }));
  // Electric nets (Amazônia)
  nets = (lvl.specialZones?.nets || []).map(n => ({
    x: n.tx*TILE, y: n.ty*TILE, active: true
  }));
  const sp = lvl.checkpoints[0] || {tx: 2, ty: grid.length - 3};
  player = _mkPlayer(sp.tx*TILE + 4, (sp.ty - 1)*TILE);
  _copyPrev();
}

// ── PLAYER ──────────────────────────────────────────────────────────
function _mkPlayer(sx, sy) {
  return {
    x: sx, y: sy, vx: 0, vy: 0, w: PW, h: PH, facing: 1, lives: 3,
    state: 'idle', onGround: false, canDjump: true, onLiana: false,
    inWater: false, iframeEnd: 0, binoOn: false,
    spawnX: sx, spawnY: sy, _ft: 0, _leg: 0
  };
}

function _updatePlayer(dt) {
  const p = player;
  const now = performance.now();
  const hurt = p.state === 'hurt';
  if (hurt && now > p.iframeEnd) p.state = 'idle';

  p.inWater = _inWater(p);
  p.onLiana = _onLiana(p);
  const grav = p.inWater ? (biome.gravityWater ?? 0.14) : GRAV;

  // Horizontal
  if (!hurt) {
    if (keys.left)       { p.vx = -RUN_SPD * dt; p.facing = -1; }
    else if (keys.right) { p.vx =  RUN_SPD * dt; p.facing =  1; }
    else                   p.vx *= 0.72;
  } else p.vx *= 0.88;

  // Lobo-Guará: foge se player corre perto
  if (Math.abs(p.vx) > 1.5) _scareShyAnimals();

  // Vertical
  if (p.onLiana && !p.inWater) {
    p.vy = 0;
    if (!hurt) {
      if (keys.up)   p.vy = -CLIMB_SPD * dt;
      if (keys.down) p.vy =  CLIMB_SPD * dt;
    }
    p.canDjump = true;
  } else if (p.inWater) {
    p.vy += (grav - 0.07) * dt;
    if (!hurt) {
      if (keys.up)   p.vy = -SWIM_SPD * dt;
      if (keys.down) p.vy =  SWIM_SPD * 0.5 * dt;
    }
    p.vy = Math.max(-SWIM_SPD, Math.min(SWIM_SPD, p.vy));
  } else {
    p.vy = Math.min(p.vy + grav * dt, MAX_FALL);
  }

  // Jump
  if (!hurt && _jp('jump')) {
    if (p.onGround) {
      p.vy = JUMP_VY; p.onGround = false; p.canDjump = true;
      _dust(p.x + PW/2, p.y + PH);
      AudioSys.play('jump');
    } else if (p.inWater) {
      p.vy = -SWIM_SPD * 1.6;
      AudioSys.play('swim');
    } else if (p.canDjump) {
      p.vy = DJUMP_VY; p.canDjump = false;
      _dust(p.x + PW/2, p.y + PH);
      AudioSys.play('djump');
    }
  }

  // Binóculo
  p.binoOn = keys.binoculo && !hurt;
  if (_jp('binoculo') && !hurt) {
    _fireBeam(p);
    _binoUsed = true;
  }

  // Interact (E)
  if (_jp('interact') && !hurt) _tryInteract();

  // Físico
  _mvX(p); _mvY(p);
  p.x = Math.max(0, Math.min(p.x, grid[0].length * TILE - p.w));

  // Pit death (cair fora do mundo)
  if (p.y > grid.length * TILE + 64) {
    _hitPlayer(3, 0, 0); // morte direta
  }

  // State
  if (!hurt) {
    if      (p.inWater)              p.state = 'swim';
    else if (p.onLiana)              p.state = 'idle';
    else if (!p.onGround && p.vy<0)  p.state = 'jump';
    else if (!p.onGround)            p.state = 'fall';
    else if (Math.abs(p.vx) > 0.4)   p.state = 'run';
    else                              p.state = 'idle';
    if (p.binoOn)                    p.state = 'bino';
  }

  // Passo animado: alterna pé esquerdo/direito
  if (p.state === 'run' && p.onGround) {
    if (!p._stepT || now - p._stepT > 210) {
      p._stepFoot = (p._stepFoot || 0) === 0 ? 1 : 0;
      const footX = p.x + PW/2 + (p._stepFoot === 0 ? -4 : 4);
      _footstep(footX, p.y + PH, p.facing);
      p._stepT = now;
    }
  }

  // Fire damage (Cerrado)
  if (biome.hasFire) {
    if (now > p._ft) {
      const tx = Math.floor((p.x + PW/2) / TILE);
      const ty = Math.floor((p.y + PH - 2) / TILE);
      if (_tAt(tx, ty) === TILES.FIRE) {
        _hitPlayer(1, 0, 0);
        AudioSys.play('fire');
        p._ft = now + (biome.fireDamageInterval ?? 900);
      }
    }
  }

  // Electric nets (Amazônia) - dano se ativas
  nets.forEach(n => {
    if (!n.active) return;
    if (p.x + PW > n.x && p.x < n.x + TILE && p.y + PH > n.y && p.y < n.y + TILE) {
      _hitPlayer(1, 60, p.x < n.x ? -1 : 1);
    }
  });

  // Steps SFX
  if (p.onGround && Math.abs(p.vx) > 1) {
    _stepTimer -= dt;
    if (_stepTimer <= 0) { AudioSys.play('step'); _stepTimer = 18; }
  }

  p._leg += Math.abs(p.vx) * 0.25;
}

// ── LOBO-GUARÁ FOGE SE CORRER ───────────────────────────────────────
function _scareShyAnimals() {
  animals.forEach(a => {
    if (a.cataloged || a.data?.catchMode !== 'slow_approach' || a._fled) return;
    const dist = Math.hypot((player.x+PW/2) - (a.x+12), (player.y+PH/2) - (a.y+12));
    if (dist < (a.data.fleeRadius ?? 130)) {
      a._fled = true;
      a._fledTime = performance.now();
      _float(a.x, a.y - 18, 'ASSUSTOU!');
    }
  });
  // Reset após 3s
  animals.forEach(a => {
    if (a._fled && performance.now() - (a._fledTime||0) > 3000) {
      a._fled = false;
    }
  });
}

// ── LILY PADS QUE AFUNDAM ───────────────────────────────────────────
function _updateLilyPads(dt) {
  if (!biome.hasWater) return;
  lilyPads.forEach(lp => {
    const px = lp.tx * TILE;
    // Lily na linha 4 (water_top) na Amazônia
    const py = 4 * TILE;
    const standing = player.x + PW > px && player.x < px + TILE
                     && player.y + PH >= py - 4 && player.y + PH <= py + 8
                     && player.onGround;
    if (standing) {
      lp.sinking = true;
      lp.sunk = Math.min(1, lp.sunk + dt * 0.012);
      if (lp.sunk >= 1) { player.onGround = false; player.y += 2; }
    } else {
      lp.sunk = Math.max(0, lp.sunk - dt * 0.008);
      if (lp.sunk <= 0) lp.sinking = false;
    }
  });
}

// ── COLLISION ───────────────────────────────────────────────────────
function _mvX(e) {
  e.x += e.vx;
  const x1 = Math.max(0, Math.floor(e.x/TILE));
  const x2 = Math.min(grid[0].length-1, Math.floor((e.x + e.w-1)/TILE));
  const y1 = Math.max(0, Math.floor(e.y/TILE));
  const y2 = Math.min(grid.length-1, Math.floor((e.y + e.h-1)/TILE));
  for (let ty = y1; ty <= y2; ty++) for (let tx = x1; tx <= x2; tx++) {
    if (!_sol(_tAt(tx, ty))) continue;
    const tl = tx * TILE;
    if (e.vx > 0 && e.x + e.w > tl && e.x < tl) { e.x = tl - e.w; e.vx = 0; }
    if (e.vx < 0 && e.x < tl + TILE && e.x + e.w > tl + TILE) { e.x = tl + TILE; e.vx = 0; }
  }
}

function _mvY(e) {
  e.y += e.vy; e.onGround = false;
  const x1 = Math.max(0, Math.floor(e.x/TILE));
  const x2 = Math.min(grid[0].length-1, Math.floor((e.x + e.w-1)/TILE));
  const y1 = Math.max(0, Math.floor(e.y/TILE));
  const y2 = Math.min(grid.length-1, Math.floor((e.y + e.h-1)/TILE));
  for (let ty = y1; ty <= y2; ty++) for (let tx = x1; tx <= x2; tx++) {
    const tile = _tAt(tx, ty); const tp = ty * TILE;
    if (_sol(tile)) {
      if (e.vy >= 0 && e.y + e.h > tp && e.y < tp) {
        e.y = tp - e.h; e.vy = 0; e.onGround = true; e.canDjump = true;
      }
      if (e.vy < 0 && e.y < tp + TILE && e.y + e.h > tp + TILE) {
        e.y = tp + TILE; e.vy = 0.5;
      }
    } else if (tile === TILES.PLATFORM && e.vy >= 0) {
      const pb = e.y + e.h - e.vy;
      if (pb <= tp + 2 && e.y + e.h >= tp) {
        e.y = tp - e.h; e.vy = 0; e.onGround = true; e.canDjump = true;
      }
    }
  }
}

function _sol(t) { return t === TILES.SOLID; }
function _tAt(tx, ty) { return (grid[ty] || [])[tx] || TILES.AIR; }
function _inWater(e) {
  if (!biome.hasWater) return false;
  return _tAt(Math.floor((e.x + e.w/2)/TILE), Math.floor((e.y + e.h/2)/TILE)) === TILES.WATER;
}
function _onLiana(e) {
  if (!biome.hasClimbing) return false;
  return _tAt(Math.floor((e.x + e.w/2)/TILE), Math.floor((e.y + 4)/TILE)) === TILES.LIANA;
}

// ── INIMIGOS ────────────────────────────────────────────────────────
function _mkEnemy(sp) {
  const def = ENEMY_TYPES[sp.type] || ENEMY_TYPES.patrulheiro;
  return {
    type: sp.type, x: sp.tx*TILE, y: (sp.ty-1)*TILE, w: def.w, h: def.h,
    vx: def.speed, vy: 0, hp: def.hpMax, facing: 1, state: 'patrol',
    stunEnd: 0,
    pl: (sp.patrol?.[0] ?? sp.tx - 4) * TILE,
    pr: (sp.patrol?.[1] ?? sp.tx + 4) * TILE,
    def, isBoss: !!sp.isBoss, bossPhase: 0,
    _chargeT: 0, _spinT: 0, _stompT: 0
  };
}

function _updateEnemies(dt) {
  const now = performance.now();
  enemies.forEach(e => {
    if (e.state === 'defeated') return;
    if (e.state === 'stunned') {
      if (now > e.stunEnd) e.state = 'patrol';
      return;
    }
    if (e.def.flies)       _moveDrone(e, dt);
    else if (e.def.aquatic) _movePiranha(e, dt);
    else if (e.isBoss)      _moveBoss(e, dt);
    else                    _movePatrol(e, dt);

    // Hit player
    if (_over(e, player) && player.state !== 'hurt') {
      _hitPlayer(1, e.def.knockback ?? 60, e.x < player.x ? 1 : -1);
    }
  });
}

function _movePatrol(e, dt) {
  e.x += e.vx * dt;
  if (e.x <= e.pl) { e.vx = e.def.speed; e.facing = 1; }
  if (e.x >= e.pr) { e.vx = -e.def.speed; e.facing = -1; }
  e.vy = Math.min(e.vy + GRAV * dt, MAX_FALL);
  e.y += e.vy;
  _resolveEY(e); _mvX(e);
}

function _moveDrone(e, dt) {
  e.x += e.vx * dt;
  if (e.x <= e.pl) { e.vx = e.def.speed; e.facing = 1; }
  if (e.x >= e.pr) { e.vx = -e.def.speed; e.facing = -1; }
  e.y += Math.sin(performance.now() * 0.002 + e.x * 0.01) * 0.5;
}

function _movePiranha(e, dt) {
  if (!player.inWater) return; // só ativa quando player na água
  e.x += e.vx * dt;
  if (e.x <= e.pl) { e.vx = e.def.speed; e.facing = 1; }
  if (e.x >= e.pr) { e.vx = -e.def.speed; e.facing = -1; }
}

function _moveBoss(e, dt) {
  const phases = e.def.phases || [];
  const newPh = phases.findIndex(p => e.hp <= p.hpThreshold);
  if (newPh > e.bossPhase) {
    e.bossPhase = newPh;
    AudioSys.play('bossRoar');
    _sparks(e.x + e.w/2, e.y + e.h/2, '#FF1744', 20);
  }
  const ph = phases[e.bossPhase] || phases[0] || {pattern:'stomp'};
  const now = performance.now();

  if (ph.pattern === 'stomp') {
    // Move devagar até o player, pisa quando perto
    const dx = player.x - e.x;
    e.vx = (dx > 0 ? 1 : -1) * e.def.speed * dt;
    e.facing = dx > 0 ? 1 : -1;
    e.x += e.vx;
    e.vy = Math.min(e.vy + GRAV * dt, MAX_FALL);
    e.y += e.vy;
    _resolveEY(e);
    if (e.onGround && Math.abs(dx) < 100) {
      e._stompT = (e._stompT || 0) + dt;
      if (e._stompT > 60) {
        _sparks(e.x + e.w/2, e.y + e.h, '#FF6D00', 12);
        AudioSys.play('land');
        e._stompT = 0;
      }
    }
  } else if (ph.pattern === 'charge') {
    // Avança rapidamente
    if (!e._chargeStart || now - e._chargeStart > 2400) {
      e._chargeDir = player.x > e.x ? 1 : -1;
      e._chargeStart = now;
    }
    e.x += e._chargeDir * e.def.speed * 2.5 * dt;
    e.facing = e._chargeDir;
    e.x = Math.max(0, Math.min(e.x, grid[0].length * TILE - e.w));
    e.vy = Math.min(e.vy + GRAV * dt, MAX_FALL);
    e.y += e.vy; _resolveEY(e);
  } else if (ph.pattern === 'spin') {
    // Movimento circular caótico + partículas
    e._spinT = (e._spinT || 0) + dt * 0.06;
    e.x += Math.cos(e._spinT) * e.def.speed * 2.5 * dt;
    e.vy = Math.min(e.vy + GRAV * dt, MAX_FALL);
    e.y += e.vy; _resolveEY(e);
    e.x = Math.max(0, Math.min(e.x, grid[0].length * TILE - e.w));
    if (Math.floor(e._spinT * 4) % 4 === 0) {
      _sparks(e.x + e.w/2, e.y + e.h/2, '#FF1744', 4);
    }
  }
}

function _resolveEY(e) {
  e.onGround = false;
  const x1 = Math.floor(e.x/TILE), x2 = Math.floor((e.x + e.w-1)/TILE);
  const y2 = Math.floor((e.y + e.h)/TILE);
  for (let tx = x1; tx <= x2; tx++) {
    if (_sol(_tAt(tx, y2))) {
      e.y = y2 * TILE - e.h; e.vy = 0; e.onGround = true;
      break;
    }
  }
}

// ── BEAMS DO BINÓCULO ───────────────────────────────────────────────
function _fireBeam(p) {
  AudioSys.play('binoFire');
  beams.push({
    x: p.x + (p.facing > 0 ? p.w : -8),
    y: p.y + PH - Math.round(_LEO_DH * 0.73),
    vx: BEAM_SPD * p.facing, w: 14, h: 6, alive: true
  });
  _sparks(p.x + (p.facing > 0 ? p.w + 4 : 0), p.y + PH - Math.round(_LEO_DH * 0.73), '#7CFC00', 5);
}

function _updateBeams(dt) {
  beams.forEach(b => {
    if (!b.alive) return;
    b.x += b.vx * dt;
    // Hit nets (Amazônia)
    nets.forEach(n => {
      if (!n.active) return;
      if (b.x + b.w > n.x && b.x < n.x + TILE && b.y + b.h > n.y && b.y < n.y + TILE) {
        n.active = false; b.alive = false;
        _sparks(n.x + TILE/2, n.y + TILE/2, '#00E5FF', 20);
        AudioSys.play('netDisable');
        _float(n.x, n.y - 16, 'REDE DESATIVADA!');
      }
    });
    // Hit enemies
    enemies.forEach(e => {
      if (e.state === 'defeated' || e.state === 'stunned' || !b.alive) return;
      if (!_over(b, e)) return;
      b.alive = false; e.hp--;
      _sparks(e.x + e.w/2, e.y + e.h/2, '#FF6D00', 10);
      AudioSys.play('stun');
      if (e.hp <= 0) {
        if (e.isBoss) {
          e.state = 'defeated';
          _sparks(e.x + e.w/2, e.y + e.h/2, '#FFD700', 30);
          setTimeout(() => {
            if (typeof showGameEnd === 'function') showGameEnd('win', App.currentBiome);
          }, 1400);
        } else {
          e.state = 'stunned';
          e.stunEnd = performance.now() + (e.def.stunMs ?? 4000);
        }
      } else {
        e.state = 'stunned';
        e.stunEnd = performance.now() + 900;
      }
    });
    if (b.x<cam.x-60||b.x>cam.x+canvas.width/(window.devicePixelRatio||1)+60) b.alive=false;
  });
  beams = beams.filter(b => b.alive);
}

// ── ANIMAIS ─────────────────────────────────────────────────────────
function _mkAnimal(sp) {
  return {
    id: sp.id, x: sp.tx * TILE, y: sp.ty * TILE - 28, w: 24, h: 24,
    data: getAnimalById(sp.id), cataloged: false,
    bob: Math.random() * Math.PI * 2,
    _fled: false, _fledTime: 0
  };
}

function _tryInteract() {
  animals.forEach(a => {
    if (a.cataloged || a._fled) return;
    const dist = Math.hypot((player.x + PW/2) - (a.x + 12), (player.y + PH/2) - (a.y + 12));
    if (dist > (a.data?.catchRadius ?? 52)) return;

    // Preguiça: precisa proteger (sem robôs ativos perto)
    if (a.data?.catchMode === 'protect') {
      const near = enemies.some(e => e.state !== 'stunned' && e.state !== 'defeated'
                                && Math.hypot(e.x - a.x, e.y - a.y) < 140);
      if (near) {
        _float(a.x, a.y - 18, 'Desative o robô primeiro!');
        return;
      }
    }

    // Boto: precisa desativar rede elétrica primeiro
    if (a.data?.catchMode === 'disable_net') {
      const blockingNet = nets.some(n => n.active && Math.hypot(n.x - a.x, n.y - a.y) < 80);
      if (blockingNet) {
        _float(a.x, a.y - 18, 'Desative a rede elétrica!');
        return;
      }
    }

    // Lobo-Guará: já tratado em _scareShyAnimals; se chegou aqui, pode catalogar

    // Catalogar!
    a.cataloged = true;
    _sparks(a.x + 12, a.y + 12, '#FFD700', 18);

    // Group save (Capivara, Quati)
    if (a.data?.catchMode === 'group_save') {
      animals.forEach(b => {
        if (!b.cataloged && b.data?.biome === a.data.biome
            && (b.data.behavior === 'group' || b.data.behavior === 'group_water')) {
          if (Math.hypot(b.x - a.x, b.y - a.y) < 200) {
            b.cataloged = true;
            _sparks(b.x + 12, b.y + 12, '#FFD700', 10);
          }
        }
      });
    }

    if (typeof showAnimalCard === 'function') showAnimalCard(a.id);
  });
}

// ── CHECKPOINTS / SAÍDA ─────────────────────────────────────────────
function _checkCheckpoints() {
  checks.forEach(cp => {
    if (cp.active) return;
    if (player.x + PW > cp.x && player.x < cp.x + TILE
        && player.y + PH > cp.y && player.y < cp.y + TILE * 2) {
      cp.active = true;
      player.spawnX = cp.x + 4; player.spawnY = cp.y;
      _sparks(cp.x + 16, cp.y, '#00BFFF', 12);
      AudioSys.play('checkpoint');
      _float(cp.x + 8, cp.y - 24, 'CHECKPOINT!');
    }
  });
}

function _checkExit() {
  const done = animals.filter(a => a.cataloged).length;
  if (done < (biome.targetCount ?? 5)) return;
  if (_over(player, exitR) && player.state !== 'hurt') {
    // Conquistas
    if (!_tookDamage && typeof App !== 'undefined')
      App.save = SaveManager.unlockAchievement(App.save, 'coracao_intacto');
    if (!_binoUsed && typeof App !== 'undefined')
      App.save = SaveManager.unlockAchievement(App.save, 'pacifista');
    if (biome.id === 'mata') {
      const t = (performance.now() - _startTime) / 1000;
      if (t < 180 && typeof App !== 'undefined')
        App.save = SaveManager.unlockAchievement(App.save, 'velocista');
    }
    AudioSys.play('exit');
    if (typeof showGameEnd === 'function') showGameEnd('win', biome.id);
  }
}

// ── HIT PLAYER ──────────────────────────────────────────────────────
function _hitPlayer(dmg, kb, dir) {
  if (player.state === 'hurt') return;
  _tookDamage = true;
  player.lives = Math.max(0, player.lives - dmg);
  player.vx = dir * (kb / 16);
  player.vy = -3;
  player.state = 'hurt';
  player.iframeEnd = performance.now() + IFRAME_MS;
  if (typeof updateHearts === 'function') updateHearts(player.lives);
  AudioSys.play('hurt');
  if (player.lives <= 0) {
    setTimeout(() => {
      if (typeof showGameEnd === 'function') showGameEnd('gameover');
    }, 700);
  }
}

// ── PARTÍCULAS / FLOATING TEXT ──────────────────────────────────────
function _sparks(x, y, col, n) {
  for (let i = 0; i < n; i++) {
    particles.push({
      x, y,
      vx: (Math.random() - 0.5) * 5,
      vy: (Math.random() - 0.5) * 5 - 1.5,
      life: 18 + Math.random() * 18,
      color: col, size: 2 + Math.random() * 3
    });
  }
}
function _dust(x, y) { _sparks(x, y, 'rgba(180,140,80,0.8)', 6); }

function _footstep(x, y, dir) {
  const side = dir > 0 ? 1 : -1;
  for (let i = 0; i < 5; i++) {
    particles.push({
      x: x + (Math.random() - 0.5) * 4,
      y: y,
      vx: side * (1.5 + Math.random() * 2.5) + (Math.random() - 0.5),
      vy: -(0.5 + Math.random() * 1.2),
      life: 10 + Math.random() * 8,
      color: `rgba(${160 + Math.random()*40|0},${120 + Math.random()*30|0},${70 + Math.random()*30|0},0.75)`,
      size: 1.5 + Math.random() * 1.5
    });
  }
}

function _updateParticles(dt) {
  particles.forEach(p => {
    p.x += p.vx * dt; p.y += p.vy * dt;
    p.vy += 0.12 * dt; p.life -= dt;
  });
  particles = particles.filter(p => p.life > 0);
}

function _float(x, y, text) { floats.push({x, y, text, life: 80}); }
function _updateFloats(dt) {
  floats.forEach(f => { f.y -= 0.4 * dt; f.life -= dt; });
  floats = floats.filter(f => f.life > 0);
}

// ── HUD ─────────────────────────────────────────────────────────────
function _updateHUD() {
  const done = animals.filter(a => a.cataloged).length;
  if (typeof updateFaunaCount === 'function')
    updateFaunaCount(done, biome.targetCount ?? 5);
  const pct = player.x / Math.max(1, (grid[0].length * TILE - PW));
  if (typeof updateMinimapPlayer === 'function') updateMinimapPlayer(pct);
  const near = enemies.some(e => e.state !== 'defeated'
                              && Math.abs(e.x - player.x) < 200
                              && Math.abs(e.y - player.y) < 140);
  if (typeof showRobotAlert === 'function') showRobotAlert(near);
}

// ── CÂMERA ──────────────────────────────────────────────────────────
function _updateCam() {
  const dpr = window.devicePixelRatio || 1;
  const cw = canvas.width / dpr, ch = canvas.height / dpr;
  const tx = player.x + PW/2 - cw/2;
  const ty = player.y + PH/2 - ch/2;
  const mx = Math.max(0, grid[0].length * TILE - cw);
  const my = Math.max(0, grid.length * TILE - ch);
  cam.x = Math.round(cam.x + (Math.max(0, Math.min(tx, mx)) - cam.x) * 0.12);
  cam.y = Math.round(cam.y + (Math.max(0, Math.min(ty, my)) - cam.y) * 0.12);
}

// ── UPDATE ──────────────────────────────────────────────────────────
function _update(dt) {
  _updatePlayer(dt);
  _updateEnemies(dt);
  _updateBeams(dt);
  _updateLilyPads(dt);
  _updateParticles(dt);
  _updateFloats(dt);
  _checkCheckpoints();
  _checkExit();
  _updateHUD();
  _updateCam();
  _copyPrev();
}

// ── DRAW ────────────────────────────────────────────────────────────
function _draw() {
  ctx.imageSmoothingEnabled = false;
  const c = biome.colors || {};
  const _d0=window.devicePixelRatio||1;
  const g = ctx.createLinearGradient(0,0,0,canvas.height/_d0);
  g.addColorStop(0, c.sky || '#4a8f6f');
  g.addColorStop(1, c.skyB || '#a8d8a8');
  ctx.fillStyle = g;
  ctx.fillRect(0,0,canvas.width/_d0,canvas.height/_d0);

  ctx.save();
  ctx.translate(-Math.round(cam.x), -Math.round(cam.y));

  _drawBg(c);
  _drawTiles(c);
  _drawNets();
  _drawChecks();
  _drawExit();
  _drawAnimals();
  _drawEnemies();
  _drawBeams();
  _drawParticles();
  _drawPlayer();
  _drawFloats();

  ctx.restore();
}

function _drawBg(c) {
  const layers = [
    {col: c.bg1 || '#1B5E20', f: 0.28, w: 40, h: 80, gap: 115, yb: 0.42},
    {col: c.bg2 || '#2E7D32', f: 0.48, w: 28, h: 55, gap: 84,  yb: 0.52},
  ];
  layers.forEach(l => {
    ctx.fillStyle = l.col + '88';
    const off = cam.x * l.f;
    const count = Math.ceil(canvas.width/(window.devicePixelRatio||1)/l.gap)+3;
    for (let i = -1; i < count; i++) {
      const bx = i * l.gap - (off % l.gap) + cam.x;
      const by = cam.y + canvas.height/(window.devicePixelRatio||1)*l.yb;
      ctx.fillRect(bx, by, l.w, l.h);
      ctx.fillRect(bx + l.w * 0.2, by - l.h * 0.55, l.w * 0.6, l.h * 0.6);
    }
  });
}

function _drawTiles(c) {
  const sx = Math.max(0, Math.floor(cam.x/TILE) - 1);
  const sy = Math.max(0, Math.floor(cam.y/TILE) - 1);
  const _d1=window.devicePixelRatio||1; const ex = Math.min(grid[0].length, sx + Math.ceil(canvas.width/_d1/TILE)+2);
  const ey = Math.min(grid.length, sy + Math.ceil(canvas.height/_d1/TILE)+2);
  const now = performance.now();

  for (let ty = sy; ty < ey; ty++) for (let tx = sx; tx < ex; tx++) {
    const tile = (grid[ty] || [])[tx] || TILES.AIR;
    if (!tile) continue;
    const px = tx * TILE, py = ty * TILE;

    switch (tile) {
      case TILES.SOLID: {
        ctx.fillStyle = c.ground || '#6D4C41';
        ctx.fillRect(px, py, TILE, TILE);
        // Textura tijolo — linhas na mesma posição absoluta em todos os tiles
        ctx.fillStyle = 'rgba(0,0,0,0.15)';
        ctx.fillRect(px, py + 16, TILE, 1);
        ctx.fillRect(px, py + 32, TILE, 1);
        ctx.fillRect(px + (tx%2===0 ? 12 : 36), py + 16, 1, 16);
        ctx.fillRect(px + (tx%2===0 ? 36 : 12), py + 32, 1, 16);
        // Topo verde somente na superfície — 1 pixel de linha
        if (_tAt(tx, ty-1) === TILES.AIR) {
          ctx.fillStyle = c.gTop || '#388E3C';
          ctx.fillRect(px, py, TILE, 6);
          ctx.fillStyle = 'rgba(200,255,200,0.25)';
          ctx.fillRect(px, py, TILE, 1);
        }
        break;
      }
      case TILES.PLATFORM: {
        // Plataforma — tábua no TOPO exato do tile
        ctx.fillStyle = c.platform || '#795548';
        ctx.fillRect(px, py, TILE, 12);
        ctx.fillStyle = 'rgba(255,220,120,0.4)';
        ctx.fillRect(px, py, TILE, 3);
        ctx.fillStyle = 'rgba(0,0,0,0.25)';
        ctx.fillRect(px, py + 10, TILE, 2);
        // Linha lateral (junta das tábuas)
        ctx.fillStyle = 'rgba(0,0,0,0.2)';
        ctx.fillRect(px + TILE - 1, py, 1, 12);
        break;
      }
      case TILES.LIANA: {
        ctx.fillStyle = c.liana || '#388E3C';
        ctx.fillRect(px + TILE/2 - 3, py, 6, TILE);
        ctx.fillStyle = 'rgba(255,255,255,0.15)';
        ctx.fillRect(px + TILE/2 - 3, py, 2, TILE);
        // Folhinhas
        ctx.fillStyle = c.gTop || '#388E3C';
        if (ty % 2 === 0) {
          ctx.fillRect(px + TILE/2 - 8, py + 6, 5, 3);
          ctx.fillRect(px + TILE/2 + 4, py + 14, 5, 3);
        }
        break;
      }
      case TILES.WATER: {
        ctx.fillStyle = (c.water || '#01579B') + 'C8';
        ctx.fillRect(px, py, TILE, TILE);
        ctx.fillStyle = 'rgba(255,255,255,0.05)';
        const sh = (Math.sin(now*0.002 + tx*0.4)*0.5 + 0.5) * TILE;
        ctx.fillRect(px, py + sh, TILE, 3);
        break;
      }
      case TILES.WATER_TOP: {
        ctx.fillStyle = c.waterS || '#0288D1';
        const wv = Math.sin(now*0.003 + tx*0.5) * 2;
        ctx.fillRect(px, py + wv, TILE, 6);
        ctx.fillStyle = (c.water || '#01579B') + 'AA';
        ctx.fillRect(px, py + 6 + wv, TILE, TILE - 6);
        break;
      }
      case TILES.FIRE: {
        ctx.fillStyle = '#BF360C';
        ctx.fillRect(px + 2, py + TILE - 10, TILE - 4, 10);
        const fl = Math.sin(now*0.008 + tx*1.3);
        [[px+6, TILE-22, 10, 14, '#FF6D00'],
         [px+14, TILE-28, 8, 20, '#FF8F00'],
         [px+22, TILE-20, 9, 13, '#FF6D00']].forEach(([fx, fy, fw, fh, fc]) => {
          ctx.fillStyle = fc;
          ctx.fillRect(fx, py + fy + fl*2, fw, fh);
        });
        ctx.fillStyle = '#FFCC02';
        ctx.fillRect(px + 14, py + TILE - 32 + fl*3, 6, 10);
        break;
      }
      case TILES.LILY: {
        // (lily pad data: na linha 4 da Amazônia)
        const lp = lilyPads.find(l => l.tx === tx);
        const sunk = lp ? lp.sunk * 8 : 0;
        ctx.fillStyle = '#2E7D32';
        ctx.beginPath();
        ctx.ellipse(px + TILE/2, py + TILE/2 + sunk, TILE/2 - 3, TILE/4, 0, 0, Math.PI*2);
        ctx.fill();
        ctx.fillStyle = '#FF8A80';
        ctx.beginPath();
        ctx.arc(px + TILE/2, py + TILE/2 + sunk, 4, 0, Math.PI*2);
        ctx.fill();
        if (lp && lp.sunk > 0.5) {
          ctx.fillStyle = 'rgba(255,255,255,0.4)';
          ctx.fillRect(px + 6, py + 4, 20, 2);
        }
        break;
      }
      case TILES.EXIT: {
        const done = animals.filter(a => a.cataloged).length >= (biome.targetCount ?? 5);
        ctx.fillStyle = done ? 'rgba(0,230,118,0.28)' : 'rgba(100,100,100,0.2)';
        ctx.fillRect(px, py, TILE, TILE*2);
        ctx.strokeStyle = done ? '#00E676' : '#555';
        ctx.lineWidth = 2;
        ctx.strokeRect(px + 3, py + 3, TILE - 6, TILE*2 - 6);
        ctx.lineWidth = 1;
        ctx.fillStyle = done ? '#69F0AE' : '#aaa';
        ctx.font = 'bold 18px monospace';
        ctx.textAlign = 'center';
        ctx.fillText('▶', px + TILE/2, py + TILE + 8);
        ctx.font = '7px "Press Start 2P",monospace';
        ctx.fillText('SAÍDA', px + TILE/2, py + TILE + 22);
        break;
      }
      case TILES.CHECKPOINT: {
        const act = checks.find(c => Math.abs(c.x - px) < 4)?.active;
        ctx.fillStyle = act ? '#FFC107' : '#B0BEC5';
        ctx.fillRect(px + 13, py - 20, 6, TILE + 20);
        ctx.fillStyle = act ? '#FFD54F' : '#ECEFF1';
        ctx.fillRect(px + 13, py - 20, 22, 14);
        break;
      }
    }
  }
}

function _drawNets() {
  nets.forEach(n => {
    if (!n.active) return;
    // Rede elétrica oscilante
    const now = performance.now();
    const flicker = Math.sin(now * 0.01);
    ctx.strokeStyle = '#00E5FF';
    ctx.lineWidth = 2;
    ctx.globalAlpha = 0.7 + flicker * 0.2;
    for (let i = 0; i < TILE; i += 6) {
      ctx.beginPath();
      ctx.moveTo(n.x + i, n.y);
      ctx.lineTo(n.x + i + 3, n.y + TILE);
      ctx.stroke();
    }
    for (let j = 0; j < TILE; j += 6) {
      ctx.beginPath();
      ctx.moveTo(n.x, n.y + j);
      ctx.lineTo(n.x + TILE, n.y + j + 3);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
    ctx.lineWidth = 1;
    // Faíscas
    if (Math.random() < 0.1) {
      _sparks(n.x + Math.random()*TILE, n.y + Math.random()*TILE, '#00E5FF', 1);
    }
  });
}

// ── PLAYER DRAW ─────────────────────────────────────────────────────
function _drawPlayer() {
  const p = player;
  const now = performance.now();
  if (p.state==='hurt' && Math.floor(now/90)%2===0) return;
  let key='idle';
  if      (p.state==='jump'||p.state==='fall')   key='jump';
  else if (Math.abs(p.vx)>0.3||p.state==='run') key='run';
  const anim=_LEO[key];
  if (!anim?.frames) return;
  const dt=now-(_leoFT||now); _leoFT=now;
  if (key!==_leoKey) { _leoFI=0; _leoKey=key; }
  else { const fps=key==='run'?14:key==='idle'?3:5; _leoFI+=dt*fps/1000; if(_leoFI>=anim.n)_leoFI-=anim.n; }
  const frame=anim.frames[Math.floor(_leoFI)%anim.n];
  if (!frame?.complete||!frame.naturalWidth) return;
  const bob = (key==='run' && p.onGround) ? Math.round(Math.sin(_leoFI/anim.n*Math.PI*2)*2) : 0;
  const dx=(p.x+PW/2-_LEO_DW/2)|0, dy=(p.y+PH-_LEO_DH+bob)|0;
  if (p.onGround && !p.onLiana && !p.inWater) {
    ctx.fillStyle='rgba(0,0,0,0.15)';
    ctx.beginPath(); ctx.ellipse((p.x+PW/2)|0,(p.y+PH+3)|0,_LEO_DW/3,4,0,0,Math.PI*2); ctx.fill();
  }
  ctx.save(); ctx.imageSmoothingEnabled=false;
  if (p.facing<0) { ctx.translate(dx+_LEO_DW,dy); ctx.scale(-1,1); ctx.drawImage(frame,0,0,_LEO_DW,_LEO_DH); }
  else ctx.drawImage(frame,dx,dy,_LEO_DW,_LEO_DH);
  ctx.restore();

  // ── Pernas animadas ──────────────────────────────────────────────
  if (key==='run' && p.onGround) {
    const phase = (_leoFI / anim.n) * Math.PI * 2;
    const cx = (p.x + PW/2)|0;
    const gy = (p.y + PH + bob)|0;          // segue o bob do sprite
    const liftA = Math.max(0,  Math.sin(phase)) * 7;
    const liftB = Math.max(0, -Math.sin(phase)) * 7;

    // Facing right → pé esquerdo (trás) depois pé direito (frente)
    // Facing left  → pé direito (trás) depois pé esquerdo (frente)
    const feet = p.facing > 0
      ? [[cx - 8, liftA], [cx + 2, liftB]]
      : [[cx + 2, liftB], [cx - 8, liftA]];

    ctx.imageSmoothingEnabled = false;
    feet.forEach(([fx, lift]) => {
      ctx.fillStyle = '#2E5C1E';            // calça (verde escuro)
      ctx.fillRect(fx, gy - 13 - lift, 6, 9);
      ctx.fillStyle = '#3E2723';            // bota (marrom escuro)
      ctx.fillRect(fx - 1, gy - 4  - lift, 8, 4);
      ctx.fillStyle = '#6D4C41';            // destaque topo da bota
      ctx.fillRect(fx,     gy - 4  - lift, 6, 1);
    });
  }
}

// ── ENEMIES DRAW ────────────────────────────────────────────────────
function _drawEnemies() {
  const now = performance.now();
  const dt  = now - (_roboFT||now); _roboFT = now;
  enemies.forEach(e => {
    if (e.state === 'defeated') return;
    ctx.globalAlpha = e.state === 'stunned' ? 0.45 : 1;
    const col = ENEMY_TYPES[e.type]?.color || '#888';

    if (e.def.flies) {
      // Drone
      ctx.fillStyle = col;
      ctx.beginPath();
      ctx.ellipse(e.x + e.w/2, e.y + e.h/2, e.w/2, e.h/2, 0, 0, Math.PI*2);
      ctx.fill();
      ctx.fillStyle = '#00E5FF';
      ctx.beginPath();
      ctx.arc(e.x + e.w/2 + (e.facing > 0 ? 6 : -6), e.y + e.h/2, 5, 0, Math.PI*2);
      ctx.fill();
      const rot = performance.now() * 0.01;
      [[-14, 0], [e.w + 2, 0]].forEach(([ox, oy]) => {
        ctx.save();
        ctx.translate(e.x + e.w/2 + ox, e.y + oy + 4);
        ctx.rotate(rot);
        ctx.fillStyle = '#90A4AE';
        ctx.fillRect(-12, -2, 24, 4);
        ctx.restore();
      });
    } else if (e.def.aquatic) {
      // Piranha
      ctx.fillStyle = col;
      ctx.beginPath();
      ctx.ellipse(e.x + e.w/2, e.y + e.h/2, e.w/2, e.h/2, 0, 0, Math.PI*2);
      ctx.fill();
      // Cauda
      ctx.fillStyle = col;
      ctx.beginPath();
      const tx = e.facing > 0 ? e.x : e.x + e.w;
      ctx.moveTo(tx, e.y + e.h/2);
      ctx.lineTo(tx + (e.facing > 0 ? -8 : 8), e.y);
      ctx.lineTo(tx + (e.facing > 0 ? -8 : 8), e.y + e.h);
      ctx.fill();
      // Olho
      ctx.fillStyle = '#00E5FF';
      ctx.fillRect(e.x + e.w/2 + (e.facing > 0 ? 4 : -8), e.y + e.h/2 - 2, 4, 4);
    } else {
      // Robô pixel art com patrol facing
      const eid = `${e.type}_${Math.round(e.pl)}`;
      if (_roboFI[eid] === undefined) _roboFI[eid] = 0;

      let rkey = 'walk';
      if (e.state === 'stunned') rkey = 'hurt';
      else if (e.state === 'attack') rkey = 'attack';

      const ranim = _ROBO[rkey] || _ROBO.walk;
      if (ranim?.frames) {
        const fps = rkey==='walk'?8 : rkey==='attack'?6 : 5;
        _roboFI[eid] += dt * fps / 1000;
        if (_roboFI[eid] >= ranim.n) _roboFI[eid] -= ranim.n;
        const rframe = ranim.frames[Math.floor(_roboFI[eid]) % ranim.n];
        if (rframe?.complete && rframe.naturalWidth) {
          const rdx = (e.x + e.w/2 - _ROBO_DW/2) | 0;
          const rdy = (e.y + e.h   - _ROBO_DH)   | 0;
          ctx.save();
          ctx.imageSmoothingEnabled = false;
          // e.facing: 1=direita, -1=esquerda — espelhar quando vai para esquerda
          if (e.facing < 0) {
            ctx.translate(rdx + _ROBO_DW, rdy);
            ctx.scale(-1, 1);
            ctx.drawImage(rframe, 0, 0, _ROBO_DW, _ROBO_DH);
          } else {
            ctx.drawImage(rframe, rdx, rdy, _ROBO_DW, _ROBO_DH);
          }
          ctx.restore();
        }
      }
    }

    // ZZZ quando stun
    if (e.state === 'stunned') {
      ctx.globalAlpha = 1;
      ctx.font = '13px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('💤', e.x + e.w/2, e.y - 6);
    }
    // Boss HP bar
    if (e.isBoss && e.state !== 'defeated') {
      ctx.globalAlpha = 1;
      ctx.fillStyle = '#263238';
      ctx.fillRect(e.x, e.y - 18, e.w, 8);
      const pct = e.hp / e.def.hpMax;
      ctx.fillStyle = pct > 0.5 ? '#4CAF50' : pct > 0.25 ? '#FF9800' : '#F44336';
      ctx.fillRect(e.x, e.y - 18, e.w * pct, 8);
      ctx.font = 'bold 8px "Press Start 2P",monospace';
      ctx.textAlign = 'center';
      ctx.fillStyle = '#fff';
      ctx.fillText('ROBÔ ALFA', e.x + e.w/2, e.y - 22);
    }
    ctx.globalAlpha = 1;
  });
}

// ── ANIMALS DRAW ────────────────────────────────────────────────────
function _drawAnimals() {
  const now = performance.now();
  animals.forEach(a => {
    if (a.cataloged) return;
    const bob = Math.sin(now*0.003 + a.bob) * 3;
    if (a._fled) ctx.globalAlpha = 0.35;
    // Halo
    ctx.fillStyle = 'rgba(255,255,220,0.18)';
    ctx.beginPath();
    ctx.arc(a.x + 12, a.y + bob + 4, 18, 0, Math.PI*2);
    ctx.fill();
    // Emoji
    ctx.font = '22px serif';
    ctx.textAlign = 'center';
    ctx.fillText(a.data?.emoji || '?', a.x + 12, a.y + bob + 6);
    // [E] indicator
    const dist = Math.hypot((player.x+PW/2)-(a.x+12), (player.y+PH/2)-(a.y+12));
    if (dist < (a.data?.catchRadius || 52) && !a._fled) {
      ctx.font = 'bold 8px "Press Start 2P",monospace';
      ctx.fillStyle = '#FFD700';
      ctx.fillText('[E]', a.x + 12, a.y + bob - 14);
    }
    ctx.globalAlpha = 1;
  });
  ctx.textAlign = 'left';
}

function _drawBeams() {
  ctx.shadowColor = '#7CFC00'; ctx.shadowBlur = 8;
  ctx.fillStyle = '#CCFF90';
  beams.forEach(b => ctx.fillRect(b.x, b.y, b.w, b.h));
  ctx.shadowBlur = 0;
}

function _drawParticles() {
  particles.forEach(p => {
    ctx.globalAlpha = Math.max(0, p.life / 28);
    ctx.fillStyle = p.color;
    ctx.fillRect(p.x - p.size/2, p.y - p.size/2, p.size, p.size);
  });
  ctx.globalAlpha = 1;
}

function _drawChecks() {
  checks.forEach(c => {
    ctx.fillStyle = c.active ? '#FFC107' : '#B0BEC5';
    ctx.fillRect(c.x + 13, c.y - 20, 6, 6);
  });
}

function _drawExit() {
  const done = animals.filter(a => a.cataloged).length >= (biome.targetCount ?? 5);
  if (!done) return;
  const now = performance.now();
  const r = Math.sin(now * 0.004) * 6 + 18;
  ctx.strokeStyle = '#00E676';
  ctx.lineWidth = 2;
  ctx.globalAlpha = Math.sin(now * 0.004) * 0.3 + 0.5;
  ctx.beginPath();
  ctx.arc(exitR.x + TILE/2, exitR.y + TILE, r, 0, Math.PI*2);
  ctx.stroke();
  ctx.globalAlpha = 1; ctx.lineWidth = 1;
}

function _drawFloats() {
  ctx.font = 'bold 10px "Press Start 2P",monospace';
  ctx.textAlign = 'center';
  floats.forEach(f => {
    ctx.globalAlpha = Math.min(1, f.life / 30);
    ctx.fillStyle = '#FFD700';
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 3;
    ctx.strokeText(f.text, f.x, f.y);
    ctx.fillText(f.text, f.x, f.y);
  });
  ctx.globalAlpha = 1; ctx.textAlign = 'left'; ctx.lineWidth = 1;
}

// ── HELPERS ─────────────────────────────────────────────────────────
function _over(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}
function _jp(k) { return keys[k] && !prev[k]; }
function _copyPrev() {
  ['left','right','up','down','jump','interact','binoculo','pause']
    .forEach(k => prev[k] = keys[k]);
}

function _resize() {
  if (!canvas) return;
  const hud = document.getElementById('hud');
  const dpr = window.devicePixelRatio || 1;
  const cssW = canvas.parentElement?.clientWidth  || window.innerWidth;
  const cssH = (canvas.parentElement?.clientHeight || window.innerHeight)
               - (hud ? hud.offsetHeight : 56);
  canvas.width  = Math.round(cssW * dpr);
  canvas.height = Math.round(cssH * dpr);
  canvas.style.width  = cssW + 'px';
  canvas.style.height = cssH + 'px';
  if (ctx) { ctx.setTransform(dpr,0,0,dpr,0,0); ctx.imageSmoothingEnabled = false; }
}

return { init, setPaused, destroy };
})();
